// The Code view on a flow as a document holds it, generated by the *compiled*
// generator, the one the browser runs. A document can hold an edge the app
// cannot use: one that names no handle, or whose id, ends or handles are not
// names (a file imported before the Flow File codec checked edges, or another
// client's write). The generator's `FlowEdge` requires string ends and both
// handles, and refuses the whole flow over one edge without them; the document
// does not hand such an edge out (`FlowDocument.getEdges`).
//
// Needs the generated module: `bun run build:wasm:codegen`.

import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import type { Edge, Node } from "@xyflow/react";
import { FlowDocument, type FlowEdge, type FlowNode } from "@microflow/collab";
import type { GenerationOutcome } from "@/lib/bindings/GenerationOutcome";
import type { ComponentType } from "@/nodes/component-types.generated";
import { resolveNodeData } from "@/nodes/node-data-resolver";
import type { SketchInvoker } from "./codegen/sketch-protocol";
import { generate_sketch, initSync } from "./codegen/generated/microflow_codegen_wasm.js";
import { projectSketchResult } from "./sketch-code-view.model";

initSync({
  module: readFileSync(new URL("./codegen/generated/microflow_codegen_wasm_bg.wasm", import.meta.url)),
});

/** The browser's `sketchInvoker` (`codegen/index.ts` over `codegen/wasm.ts`), on the module loaded above. */
const compiledGenerator: SketchInvoker = async (command) => {
  try {
    const outcome = generate_sketch(JSON.stringify(command.flow), command.targetId, undefined);
    return { success: true, data: JSON.parse(outcome) as GenerationOutcome };
  } catch (error) {
    return { success: false, error: error instanceof Error ? error.message : String(error) };
  }
};

function node(id: string, type: ComponentType): FlowNode {
  const resolved = resolveNodeData(type, {});
  if (!resolved.ok) throw new Error(resolved.error);
  return { id, type, position: { x: 0, y: 0 }, data: resolved.data };
}

/**
 * What the Code view shows for a flow that holds these nodes and edges, and
 * `stored` written into the document exactly as given, under the key `bad`.
 */
async function codeViewOf(nodes: FlowNode[], edges: FlowEdge[], stored?: unknown) {
  const doc = FlowDocument.createEmpty();
  try {
    doc.setFlowData(nodes, edges);
    if (stored !== undefined) {
      doc.doc.transact(() => (doc.edges as unknown as Map<string, unknown>).set("bad", stored));
    }
    return await projectSketchResult(compiledGenerator, doc.getNodes() as Node[], doc.getEdges() as Edge[], "uno");
  } finally {
    doc.destroy();
  }
}

describe("the Code view of a flow that holds a malformed edge", () => {
  const nodes = [node("btn", "Button"), node("led", "Led")];
  const wired: FlowEdge = { id: "wired", source: "btn", sourceHandle: "event", target: "led", targetHandle: "toggle" };
  const generatedAt = /^\/\/ Generated at: .*\n/m;

  const MALFORMED: Array<[string, unknown]> = [
    ["no handle", { id: "e", source: "btn", target: "led" }],
    ["not an edge", 7],
    ["an id that is not a name", { ...wired, id: 5 }],
    ["a source that is not a name", { ...wired, id: "e", source: 3 }],
    ["a target that is not a name", { ...wired, id: "e", target: null }],
    ["a handle that is not a name", { ...wired, id: "e", sourceHandle: 3 }],
    ["a handle that is an object", { ...wired, id: "e", targetHandle: { x: 1 } }],
  ];

  test.each(MALFORMED)("an edge with %s does not keep the flow from exporting", async (_, stored) => {
    const shown = await codeViewOf(nodes, [wired], stored);

    expect(shown.isError).toBe(false);
    expect(shown.value).toContain("void setup()");
  });

  test.each(MALFORMED)("an edge with %s is not in the sketch: it is the flow's without it", async (_, stored) => {
    const withIt = (await codeViewOf(nodes, [wired], stored)).value;
    const without = (await codeViewOf(nodes, [wired])).value;

    expect(withIt.replace(generatedAt, "")).toBe(without.replace(generatedAt, ""));
  });
});
